@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-card {
    --_nz-card-bg: var(--nz-bg-surface);
    --_nz-card-border: var(--nz-border-subtle);
    --_nz-card-padding: var(--nz-space-6);
    --_nz-card-shadow: none;
    /* the Delta pill fill a tinted Card sets for the Deltas inside it (below); an untinted Card
       resets it, so a Delta follows its nearest Card */
    --_nz-card-pill: initial;

    display: flex;
    flex-direction: column;
    gap: var(--nz-card-gap, var(--nz-space-5));
    padding: var(--nz-card-padding, var(--_nz-card-padding));
    border: var(--nz-border-width-default) solid var(--nz-card-border, var(--_nz-card-border));
    border-radius: var(--nz-card-radius, var(--nz-radius-xl));
    background: var(--nz-card-bg, var(--_nz-card-bg));
    /* the surface painted above, hook included, for children; a light-dark() value stays unresolved
       in a custom property, so it resolves in the reader's scheme (the inverse one inside inverse) */
    --nz-surface: var(--nz-card-bg, var(--_nz-card-bg));
    box-shadow: var(--nz-card-shadow, var(--_nz-card-shadow));
    color: var(--nz-text-primary);
  }

  .nz-card[data-tone='subtle'] {
    --_nz-card-bg: var(--nz-bg-subtle);
    --_nz-card-border: transparent;
  }

  .nz-card[data-tone='brand'] {
    --_nz-card-bg: var(--nz-bg-brand-subtle);
    --_nz-card-border: transparent;
    --_nz-card-pill: var(--nz-bg-surface);
  }

  .nz-card[data-tone='accent'] {
    --_nz-card-bg: var(--nz-bg-accent-subtle);
    --_nz-card-border: transparent;
    --_nz-card-pill: var(--nz-bg-surface);
  }

  .nz-card:is([data-tone='brand'], [data-tone='accent']) .nz-delta {
    --_nz-delta-fill: var(--_nz-card-pill);
  }

  .nz-card[data-padding='sm'] {
    --_nz-card-padding: var(--nz-space-5);
  }

  .nz-card[data-elevation='1'] {
    --_nz-card-shadow: var(--nz-elevation-1);
  }

  /* bg/surface here resolves in the inverse scheme set by data-nz-scheme */
  .nz-card[data-tone='inverse'] {
    --_nz-card-border: transparent;
  }

  /* title and description in the first column; the action, when present, opens a second one */
  .nz-card-header {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: center;
    gap: var(--nz-space-1) var(--nz-space-3);
  }

  .nz-card-title {
    grid-column: 1;
    margin: 0;
    font: var(--nz-card-title-font, var(--nz-font-heading-h4));
    letter-spacing: var(--nz-tracking-heading-h4);
  }

  .nz-card-description {
    grid-column: 1;
    margin: 0;
    color: var(--nz-text-secondary);
    font: var(--nz-font-body-m);
  }

  .nz-card-action {
    display: flex;
    grid-area: 1 / 2;
    align-items: center;
    gap: var(--nz-space-2);
    color: var(--nz-icon-secondary);
  }

  .nz-card-body {
    min-inline-size: 0;
  }

  .nz-card-footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--nz-space-3);
  }

  /* backgrounds and shadows are replaced: the border carries the edge for every tone */
  @media (forced-colors: active) {
    .nz-card {
      border-color: CanvasText;
    }
  }
}
